INSERT INTO "LabCatalogParameter" ("id","testId","code","nameUz","nameRu","nameEn","unit","valueType","note","referenceRanges","sortOrder") VALUES ('271ce8cc-02bd-5bc2-81bf-5a22104eca84','8b1c7522-3878-584f-9b44-43ba5417895e','ESR','Eritrotsitlarning cho''kish tezligi (ECHT)','Скорость оседания эритроцитов (СОЭ)','Erythrocyte Sedimentation Rate','mm/h','NUMERIC'::"LabValueType",'Метод Вестергрена (Westergren) / Метод Панченкова (г. Ташкент / Минздрав РУз). Основные диапазоны даны по Вестергрену; значения по Панченкову указаны в примечаниях к строкам','[{"ageMinDays":0,"ageMaxDays":30,"low":0,"high":2,"label":"Новорожденные","note":"Источник не указывает возрастные границы для группы «Новорожденные»; принято 0-30 дней"},{"ageMinDays":0,"ageMaxDays":4380,"low":2,"high":10,"label":"Дети до 12 лет","note":"по Панченкову: 2-8 мм/ч. Нижняя граница возраста в источнике не указана, поэтому строка перекрывается со строкой «Новорожденные»"},{"gender":"MALE","ageMaxDays":18250,"low":2,"high":15,"label":"Мужчины (до 50 лет)","note":"по Панченкову: 2-10 мм/ч"},{"gender":"MALE","ageMinDays":18250,"low":2,"high":20,"label":"Мужчины (> 50 лет)"},{"gender":"FEMALE","ageMaxDays":18250,"low":2,"high":20,"label":"Женщины (до 50 лет)","note":"по Панченкову: 2-15 мм/ч"},{"gender":"FEMALE","ageMinDays":18250,"low":2,"high":30,"label":"Женщины (> 50 лет)"},{"gender":"FEMALE","state":"PREGNANCY_T2","low":0,"high":40,"label":"Беременность (со II триместра)","note":"Источник: «до 40 - 55 мм/ч» — верхний порог задан диапазоном; взято нижнее из указанных значений (40). Источник указывает «со II триместра», строка продублирована для II и III триместров"},{"gender":"FEMALE","state":"PREGNANCY_T3","low":0,"high":40,"label":"Беременность (со II триместра)","note":"Источник: «до 40 - 55 мм/ч» — верхний порог задан диапазоном; взято нижнее из указанных значений (40). Источник указывает «со II триместра», строка продублирована для II и III триместров"}]'::jsonb,0) ON CONFLICT ("testId","code") DO NOTHING;
