INSERT INTO "LabCatalogParameter" ("id","testId","code","nameUz","nameRu","nameEn","unit","valueType","note","referenceRanges","sortOrder") VALUES ('d363bb73-4dc9-5f63-8ce9-71fa6545e704','87df60a5-b2d4-5231-bb6b-87fb0afa66ed','RET','Retikulotsitlar','Ретикулоциты','Reticulocytes','%','NUMERIC'::"LabValueType",'Источник указывает единицы: % (промилле, ‰) или 10^9/л; взята первая названная система (%), остальные значения записаны в примечаниях к диапазонам','[{"ageMinDays":0,"ageMaxDays":30,"low":1.5,"high":5,"label":"Новорожденные","note":"то же в промилле: 15 - 50 ‰; в абсолютных значениях: 60 - 200 x 10^9/л. Источник не указывает возрастные границы для группы «Новорожденные»; принято 0-30 дней (до начала следующей группы «от 1 месяца»)"},{"ageMinDays":30,"low":0.5,"high":2,"label":"Дети от 1 месяца и взрослые","note":"то же в промилле: 5 - 20 ‰; в абсолютных значениях: 25 - 90 x 10^9/л"}]'::jsonb,0) ON CONFLICT ("testId","code") DO NOTHING;
