INSERT INTO "LabCatalogParameter" ("id","testId","code","nameUz","nameRu","nameEn","unit","valueType","note","referenceRanges","sortOrder") VALUES ('6b7a8765-b61c-5938-90d4-f3f48a0c8f57','c765042b-2675-5097-9cb0-84c21e6cb1f7','GLU','Glyukoza','Глюкоза','Glucose','mmol/L','NUMERIC'::"LabValueType",'Источник (строка 154): [Критические значения: < 2.2 ммоль/л (у новорожденных < 1.7) или > 25.0 ммоль/л]. Возрастной интервал 14-15 лет источником не покрыт.','[{"ageMinDays":0,"ageMaxDays":30,"low":1.7,"high":4.4,"criticalLow":1.7,"criticalHigh":25,"label":"Новорожденные","note":"Источник не указывает числовой возрастной предел для «Новорожденные»; принят интервал 0-30 дней, так как следующая строка начинается с 1 месяца. Критический нижний порог для новорожденных источник указывает как < 1.7 ммоль/л."},{"ageMinDays":30,"ageMaxDays":5110,"low":3.3,"high":5.5,"criticalLow":2.2,"criticalHigh":25,"label":"Дети (1 мес. - 14 лет)"},{"ageMinDays":5475,"ageMaxDays":21900,"low":4.1,"high":5.9,"criticalLow":2.2,"criticalHigh":25,"label":"Взрослые (15-60 лет)","note":"в капиллярной крови: 3.3 - 5.5 ммоль/л"},{"ageMinDays":21900,"ageMaxDays":32850,"low":4.4,"high":6.4,"criticalLow":2.2,"criticalHigh":25,"label":"Лица 60-90 лет"},{"ageMinDays":32850,"low":4.6,"high":6.7,"criticalLow":2.2,"criticalHigh":25,"label":"Лица старше 90 лет"},{"gender":"FEMALE","state":"PREGNANCY","low":4,"high":5.1,"criticalLow":2.2,"criticalHigh":25,"label":"Беременные женщины (строгий порог гестационного СД)"}]'::jsonb,0) ON CONFLICT ("testId","code") DO NOTHING;
