INSERT INTO "LabCatalogParameter" ("id","testId","code","nameUz","nameRu","nameEn","unit","valueType","note","referenceRanges","sortOrder") VALUES ('0f869db8-0652-5d7b-ab11-8792560b5977','a59d6dd4-a126-548d-a22a-861c100d7a50','HBA1C','Glikirlangan gemoglobin','Гликированный гемоглобин','Glycated Hemoglobin','%','NUMERIC'::"LabValueType",'Источник указывает две системы единиц: % и IFCC (ммоль/моль); использована первая — %. Соответствия IFCC приведены в примечаниях к строкам. Строки «Предиабет», «Сахарный диабет» и «Целевой уровень при СД» — не референсные интервалы нормы, а диагностические/целевые пороги источника.','[{"low":4,"high":5.6,"label":"Норма (все возраста)","note":"20 - 38 ммоль/моль (IFCC)"},{"low":5.7,"high":6.4,"label":"Предиабет / Нарушение толерантности","note":"39 - 46 ммоль/моль (IFCC). Диагностический интервал, не норма."},{"low":6.5,"label":"Сахарный диабет","note":"Источник: «≥ 6.5 % (≥ 48 ммоль/моль)». Диагностический порог, не норма."},{"high":7,"label":"Целевой уровень при СД (взрослые)","note":"Источник: «< 7.0 %». Целевой порог терапии, не референсная норма. Числовой возраст «взрослые» источником не задан."}]'::jsonb,0) ON CONFLICT ("testId","code") DO NOTHING;
