INSERT INTO "LabCatalogParameter" ("id","testId","code","nameUz","nameRu","nameEn","unit","valueType","note","referenceRanges","sortOrder") VALUES ('db04da47-42a5-54f2-ac42-aa3a9588dffe','b887732f-5136-55b6-8950-4c60c3b9ae8e','ALP','Ishqoriy fosfataza','Щелочная фосфатаза','Alkaline Phosphatase','U/L','NUMERIC'::"LabValueType",'Примечание источника: у детей активность значительно выше из-за активного остеогенеза. Возрастные интервалы 1-12 мес., 3-4 года, 9-10 лет, 15-20 лет и старше 60 лет источником не покрыты.','[{"ageMinDays":0,"ageMaxDays":30,"low":70,"high":370,"label":"Новорожденные","note":"Числовой возрастной предел для «Новорожденные» источником не задан; принят интервал 0-30 дней."},{"ageMinDays":365,"ageMaxDays":1095,"low":100,"high":350,"label":"Дети 1-3 года"},{"ageMinDays":1460,"ageMaxDays":3285,"low":140,"high":360,"label":"Дети 4-9 лет"},{"ageMinDays":3650,"ageMaxDays":5475,"low":130,"high":500,"label":"Подростки 10-15 лет (период вытяжения)"},{"gender":"MALE","ageMinDays":7300,"ageMaxDays":21900,"low":40,"high":130,"label":"Взрослые мужчины (20-60 лет)"},{"gender":"FEMALE","ageMinDays":7300,"ageMaxDays":21900,"low":35,"high":105,"label":"Взрослые женщины (20-60 лет)"},{"gender":"FEMALE","state":"PREGNANCY_T3","low":0,"high":250,"label":"Беременность (III триместр, плацентарная изоформа)","note":"Источник: «до 250 - 300 Ед/л» — верхний порог задан диапазоном; взято нижнее число 250."}]'::jsonb,0) ON CONFLICT ("testId","code") DO NOTHING;
INSERT INTO "LabCatalogTest" ("id","code","biomaterial","category","nameUz","nameRu","nameEn","specimenNote","sortOrder") VALUES ('7f566222-28cd-53e0-823b-b01e8d21ad90','BILIRUBIN_TOTAL','BLOOD'::"Biomaterial",'BIOCHEMISTRY'::"LabCategory",'Umumiy bilirubin','Билирубин общий','Total Bilirubin',NULL,14) ON CONFLICT ("code") DO NOTHING;
INSERT INTO "LabCatalogParameter" ("id","testId","code","nameUz","nameRu","nameEn","unit","valueType","note","referenceRanges","sortOrder") VALUES ('04223fab-13c9-5454-9f8e-2e5bcab9bfa2','7f566222-28cd-53e0-823b-b01e8d21ad90','TBIL','Umumiy bilirubin','Билирубин общий','Total Bilirubin','umol/L','NUMERIC'::"LabValueType",'Источник (строка 212): [Критические значения: у новорожденных > 250-300 мкмоль/л (риск ядерной желтухи)] — порог задан диапазоном, взято нижнее число 250. Источник адресует критическое значение новорожденным, но по правилу каталога критические значения задаются на уровне параметра и проставлены во всех строках. Возраст 6-30 дней источником не покрыт.','[{"ageMinDays":0,"ageMaxDays":1,"low":0,"high":68,"criticalHigh":250,"label":"Новорожденные (1-й день)","note":"Источник: «до 68 мкмоль/л»"},{"ageMinDays":1,"ageMaxDays":2,"low":0,"high":150,"criticalHigh":250,"label":"Новорожденные (2-й день)","note":"Источник: «до 150 мкмоль/л»"},{"ageMinDays":2,"ageMaxDays":5,"low":0,"high":205,"criticalHigh":250,"label":"Новорожденные (3-5 дни, пик желтухи)","note":"Источник: «до 205 мкмоль/л (у недоношенных до 255)»"},{"ageMinDays":30,"low":3.4,"high":20.5,"criticalHigh":250,"label":"Дети старше 1 месяца и взрослые","note":"Критическое значение 250 мкмоль/л применено ко всем строкам параметра, как требует правило (критические значения задаются на уровне параметра). В источнике строка критических значений адресована новорожденным: «у новорожденных > 250-300 мкмоль/л (риск ядерной желтухи)»."}]'::jsonb,0) ON CONFLICT ("testId","code") DO NOTHING;
