INSERT INTO "LabCatalogParameter" ("id","testId","code","nameUz","nameRu","nameEn","unit","valueType","note","referenceRanges","sortOrder") VALUES ('574ea3be-7474-54c1-a677-ea2474add12a','3c483c5d-a374-5e53-ba43-970566fc4ce0','TP','Umumiy oqsil','Общий белок','Total Protein','g/L','NUMERIC'::"LabValueType",'Возрастные интервалы 4-5 лет и 14-15 лет источником не покрыты.','[{"ageMinDays":0,"ageMaxDays":30,"low":46,"high":68,"label":"Новорожденные","note":"Числовой возрастной предел для «Новорожденные» источником не задан; принят интервал 0-30 дней, так как следующая строка охватывает грудной возраст."},{"ageMinDays":30,"ageMaxDays":365,"low":48,"high":72,"label":"Грудные дети (до 1 года)","note":"Источник пишет «до 1 года»; нижняя граница принята как 30 дней, поскольку период 0-30 дней покрыт строкой новорожденных."},{"ageMinDays":365,"ageMaxDays":1460,"low":56,"high":75,"label":"Дети 1-4 года"},{"ageMinDays":1825,"ageMaxDays":5110,"low":60,"high":80,"label":"Дети 5-14 лет"},{"ageMinDays":5475,"ageMaxDays":21900,"low":64,"high":83,"label":"Взрослые (15-60 лет)","note":"В источнике в скобках дан альтернативный интервал: 65 - 85 г/л"},{"ageMinDays":21900,"low":62,"high":81,"label":"Лица старше 60 лет"},{"gender":"FEMALE","state":"PREGNANCY","low":55,"high":75,"label":"Беременность","note":"физиологическая гемодилюция"}]'::jsonb,0) ON CONFLICT ("testId","code") DO NOTHING;
