INSERT INTO "LabCatalogParameter" ("id","testId","code","nameUz","nameRu","nameEn","unit","valueType","note","referenceRanges","sortOrder") VALUES ('a75a4338-c838-5279-bbe7-d9c93e98f037','8deed351-0c61-5f4a-8537-9073d9d44aee','CREATININE','Kreatinin','Креатинин','Creatinine','umol/L','NUMERIC'::"LabValueType",'Источник: «Единицы измерения: мкмоль/л (µmol/L)». Критические значения в источнике заданы диапазоном: «[Критические значения: > 400 - 500 мкмоль/л (показание к гемодиализу при ОПП/ХПН)]» — в criticalHigh взято нижнее число 400.','[{"ageMinDays":0,"ageMaxDays":30,"low":27,"high":88,"criticalHigh":400,"label":"Новорожденные","note":"Источник не указывает числовых границ возраста для «Новорожденные»; верхняя граница 30 дней принята условно (в источнике числа нет). Следующая полоса «Дети до 1 года» начинается с 0 дней и перекрывает эту."},{"ageMinDays":0,"ageMaxDays":365,"low":18,"high":35,"criticalHigh":400,"label":"Дети до 1 года","note":"Источник говорит «Дети до 1 года» без нижней границы, поэтому нижняя граница = 0 дней (как «Дети до 12 лет» у мочевой кислоты). Полоса перекрывается с полосой «Новорожденные» — так в источнике."},{"ageMinDays":365,"ageMaxDays":1825,"low":27,"high":42,"criticalHigh":400,"label":"Дети 1-5 лет"},{"ageMinDays":2190,"ageMaxDays":4015,"low":32,"high":62,"criticalHigh":400,"label":"Дети 6-11 лет","note":"В источнике между полосами «1-5 лет» и «6-11 лет» остается непокрытый интервал 5-6 лет."},{"ageMinDays":4380,"ageMaxDays":5475,"low":44,"high":88,"criticalHigh":400,"label":"Подростки 12-15 лет","note":"В источнике между полосами «6-11 лет» и «12-15 лет» остается непокрытый интервал 11-12 лет."},{"gender":"MALE","ageMinDays":5840,"ageMaxDays":21900,"low":62,"high":115,"criticalHigh":400,"label":"Взрослые мужчины (16-60 лет)","note":"до 106 по IDMS-стандарту"},{"gender":"FEMALE","ageMinDays":5840,"ageMaxDays":21900,"low":44,"high":97,"criticalHigh":400,"label":"Взрослые женщины (16-60 лет)","note":"до 88 по IDMS-стандарту"},{"gender":"MALE","ageMinDays":21900,"low":71,"high":115,"criticalHigh":400,"label":"Пожилые (>60 лет): Мужчины"},{"gender":"FEMALE","ageMinDays":21900,"low":53,"high":106,"criticalHigh":400,"label":"Пожилые (>60 лет): Женщины"},{"gender":"FEMALE","state":"PREGNANCY","low":35,"high":70,"criticalHigh":400,"label":"Беременность","note":"физиологическое повышение СКФ"}]'::jsonb,0) ON CONFLICT ("testId","code") DO NOTHING;
