INSERT INTO "LabCatalogParameter" ("id","testId","code","nameUz","nameRu","nameEn","unit","valueType","note","referenceRanges","sortOrder") VALUES ('95c1d2d2-a453-522e-9ba1-96d6d235e081','cfeb521c-7737-5c6e-9cfb-89304a53a890','EGFR','Hisoblangan koptokchali filtratsiya tezligi (eGFR)','Расчетная скорость клубочковой фильтрации (eGFR)','Estimated Glomerular Filtration Rate (eGFR)','mL/min/1.73m^2','NUMERIC'::"LabValueType",'Расчетный показатель, формула CKD-EPI. Источник, помимо нормы, приводит классификацию стадий ХБП (это стадии болезни, а не референсные интервалы, поэтому в ranges они не внесены): «Начальное снижение (ХБП С2): 60 - 89 мл/мин/1.73 м²; Умеренное снижение (ХБП С3а): 45 - 59 мл/мин/1.73 м²; Существенное снижение (ХБП С3б): 30 - 44 мл/мин/1.73 м²; Тяжелое снижение (ХБП С4): 15 - 29 мл/мин/1.73 м²; Терминальная почечная недостаточность (ХБП С5): < 15 мл/мин/1.73 м²».','[{"low":90,"label":"Норма (взрослые)","note":"формула CKD-EPI; источник указывает «Взрослые» без числовых границ возраста"}]'::jsonb,0) ON CONFLICT ("testId","code") DO NOTHING;
