INSERT INTO "LabCatalogParameter" ("id","testId","code","nameUz","nameRu","nameEn","unit","valueType","note","referenceRanges","sortOrder") VALUES ('ffc483d9-3da0-5a5c-81ab-d111a581f1e3','9b528160-5516-5525-956e-b911b7b93979','TOTAL_CHOLESTEROL','Umumiy xolesterin','Общий холестерин','Total Cholesterol','mmol/L','NUMERIC'::"LabValueType",'Источник приводит градации: у детей и подростков (<18 лет) «Желательный: < 4.4 ммоль/л; Пограничный: 4.4 - 5.1; Высокий: > 5.2 ммоль/л»; у взрослых «Оптимальный: < 5.0 ммоль/л; Погранично-повышенный: 5.0 - 6.2 ммоль/л; Высокий: > 6.2 ммоль/л». В ranges внесены только желательный/оптимальный уровни, остальные градации — патологические классы.','[{"ageMinDays":0,"ageMaxDays":6570,"high":4.4,"label":"Дети и подростки (<18 лет): Желательный","note":"Пограничный: 4.4 - 5.1; Высокий: > 5.2 ммоль/л"},{"high":5,"label":"Взрослые (общая популяция): Оптимальный","note":"Погранично-повышенный: 5.0 - 6.2 ммоль/л; Высокий: > 6.2 ммоль/л. Источник указывает «Взрослые» без числовых границ возраста."}]'::jsonb,0) ON CONFLICT ("testId","code") DO NOTHING;
INSERT INTO "LabCatalogParameter" ("id","testId","code","nameUz","nameRu","nameEn","unit","valueType","note","referenceRanges","sortOrder") VALUES ('746ad3fb-7bc4-5ca1-8b02-126acaf76000','9b528160-5516-5525-956e-b911b7b93979','HDL_CHOLESTEROL','YuZLP xolesterini (HDL)','Холестерин ЛПВП / Альфа-холестерин','HDL-Cholesterol','mmol/L','NUMERIC'::"LabValueType",'Уровень < 1.0 у мужчин и < 1.2 у женщин является независимым фактором кардиоваскулярного риска','[{"gender":"MALE","low":1,"label":"Мужчины","note":"оптимально > 1.2"},{"gender":"FEMALE","low":1.2,"label":"Женщины","note":"оптимально > 1.4"}]'::jsonb,1) ON CONFLICT ("testId","code") DO NOTHING;
INSERT INTO "LabCatalogParameter" ("id","testId","code","nameUz","nameRu","nameEn","unit","valueType","note","referenceRanges","sortOrder") VALUES ('66f85046-d03a-5798-98e7-f94863f75c3e','9b528160-5516-5525-956e-b911b7b93979','LDL_CHOLESTEROL','PZLP xolesterini (LDL)','Холестерин ЛПНП','LDL-Cholesterol','mmol/L','NUMERIC'::"LabValueType",'Источник: «Единицы измерения: ммоль/л (целевые значения по категориям риска ESC/Минздрав РУз)» — интервалы ниже являются целевыми уровнями по категории сердечно-сосудистого риска, а не возрастными нормами.','[{"high":3,"label":"Низкий кардиориск"},{"high":2.6,"label":"Умеренный кардиориск"},{"high":1.8,"label":"Высокий кардиориск","note":"и снижение на ≥50% от исходного"},{"high":1.4,"label":"Очень высокий кардиориск (ИБС, перенесенный ИМ, инсульт, СД)"}]'::jsonb,2) ON CONFLICT ("testId","code") DO NOTHING;
