INSERT INTO "LabCatalogParameter" ("id","testId","code","nameUz","nameRu","nameEn","unit","valueType","note","referenceRanges","sortOrder") VALUES ('4a6f9ebd-177b-56b0-a60f-3dbea8da3649','9b528160-5516-5525-956e-b911b7b93979','TRIGLYCERIDES','Triglitseridlar','Триглицериды','Triglycerides (TG)','mmol/L','NUMERIC'::"LabValueType",'Градации у взрослых по источнику: «Оптимальный: < 1.7 ммоль/л; Пограничный: 1.7 - 2.2 ммоль/л; Высокий: 2.3 - 5.6 ммоль/л; Очень высокий (риск панкреатита): > 5.6 ммоль/л». В ranges внесен только оптимальный уровень.','[{"ageMinDays":0,"ageMaxDays":3650,"high":1.1,"label":"Дети (<10 лет)"},{"ageMinDays":3650,"ageMaxDays":6570,"high":1.4,"label":"Подростки (10-18 лет)"},{"high":1.7,"label":"Взрослые: Оптимальный","note":"Пограничный: 1.7 - 2.2 ммоль/л; Высокий: 2.3 - 5.6 ммоль/л; Очень высокий (риск панкреатита): > 5.6 ммоль/л. Источник указывает «Взрослые» без числовых границ возраста."}]'::jsonb,4) ON CONFLICT ("testId","code") DO NOTHING;
